package com.example.tourismmedia.ui.challenges;

import android.view.LayoutInflater;import android.view.View;import android.view.ViewGroup;import android.widget.*;import androidx.annotation.NonNull;import androidx.recyclerview.widget.RecyclerView;import com.example.tourismmedia.R;import com.example.tourismmedia.data.model.AppModels.Challenge;import java.util.*;

class ChallengeAdapter extends RecyclerView.Adapter<ChallengeAdapter.Holder>{interface Listener{void click(Challenge challenge);}private final List<Challenge>items=new ArrayList<>();private final Listener listener;ChallengeAdapter(Listener listener){this.listener=listener;}void submit(List<Challenge>data){items.clear();items.addAll(data);notifyDataSetChanged();}@NonNull public Holder onCreateViewHolder(@NonNull ViewGroup p,int t){return new Holder(LayoutInflater.from(p.getContext()).inflate(R.layout.item_challenge_card,p,false));}public void onBindViewHolder(@NonNull Holder h,int p){Challenge x=items.get(p);int target=x.target>0?x.target:x.requiredCheckins;int percent=x.percent>0?x.percent:(target>0?Math.min(100,x.progress*100/target):0);h.title.setText(x.name);h.meta.setText(x.progress+"/"+target+" hoàn thành · +"+x.rewardPoint+" điểm");h.progress.setProgress(percent);h.icon.setText(p%2==0?"🌿":"🍜");h.itemView.setOnClickListener(v->listener.click(x));}public int getItemCount(){return items.size();}static class Holder extends RecyclerView.ViewHolder{TextView title,meta,icon;ProgressBar progress;Holder(View v){super(v);title=v.findViewById(R.id.challenge_title);meta=v.findViewById(R.id.challenge_meta);icon=v.findViewById(R.id.challenge_icon);progress=v.findViewById(R.id.challenge_progress);}}}
